('gym-visual-exercises-dataset', '0078', '7455efae41b330c265e7cd4b78dfa848e7ce5ebd', 'barbell rear lunge', 'barbell rear lunge', '[]', 'upper legs', 'upper legs', '["quadriceps"]', '["quadriceps", "hamstrings", "calves"]', 'barbell', '未评估', '未评估', '[]', NULL, 'PENDING', 0, '首先，双脚分开与肩同宽，将杠铃放在上背部。 右脚向后退一步，用脚掌着地。 弯曲双膝降低身体，直到左大腿与地面平行。 推动左脚跟返回到起始位置。 换另一条腿重复上述步骤。', '["首先，双脚分开与肩同宽，将杠铃放在上背部。", "右脚向后退一步，用脚掌着地。", "弯曲双膝降低身体，直到左大腿与地面平行。", "推动左脚跟返回到起始位置。", "换另一条腿重复上述步骤。"]', '/assets/media/exercises/images/0078-VaP75jl.jpg', '/assets/media/exercises/videos/0078-VaP75jl.gif', 'LICENSED', '© Gym visual — https://gymvisual.com/', NOW(), NOW()),
