('gym-visual-exercises-dataset', '0140', '7455efae41b330c265e7cd4b78dfa848e7ce5ebd', 'biceps pull-up', 'biceps pull-up', '[]', 'upper arms', 'upper arms', '["forearms"]', '["forearms", "shoulders"]', 'body weight', '未评估', '未评估', '[]', NULL, 'PENDING', 0, '悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。 启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。 在动作的最高点暂停，然后慢慢降低回到起始位置。 重复所需的重复次数。', '["悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。", "启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。", "在动作的最高点暂停，然后慢慢降低回到起始位置。", "重复所需的重复次数。"]', '/assets/media/exercises/images/0140-guT8YnS.jpg', '/assets/media/exercises/videos/0140-guT8YnS.gif', 'LICENSED', '© Gym visual — https://gymvisual.com/', NOW(), NOW()),
