('gym-visual-exercises-dataset', '2189', '7455efae41b330c265e7cd4b78dfa848e7ce5ebd', 'dumbbells seated triceps extension', 'dumbbells seated triceps extension', '[]', 'upper arms', 'upper arms', '["shoulders"]', '["shoulders"]', 'dumbbell', '未评估', '未评估', '[]', NULL, 'PENDING', 0, '坐在长凳上，背部挺直，双脚平放在地上。 双手握住哑铃，正握，将其举过头顶。 弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。 伸展双臂，将哑铃举回到起始位置。 重复所需的重复次数。', '["坐在长凳上，背部挺直，双脚平放在地上。", "双手握住哑铃，正握，将其举过头顶。", "弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。", "伸展双臂，将哑铃举回到起始位置。", "重复所需的重复次数。"]', '/assets/media/exercises/images/2189-FQXdXzY.jpg', '/assets/media/exercises/videos/2189-FQXdXzY.gif', 'LICENSED', '© Gym visual — https://gymvisual.com/', NOW(), NOW()),
('gym-visual-exercises-dataset', '1167', '7455efae41b330c265e7cd4b78dfa848e7ce5ebd', 'dynamic chest stretch (male)', 'dynamic chest stretch (male)', '[]', 'chest', 'chest', '["shoulders"]', '["shoulders", "triceps"]', 'body weight', '未评估', '未评估', '[]', NULL, 'PENDING', 0, '站直，双脚分开与肩同宽。 将双臂伸直至两侧，与地面平行。 慢慢地将双臂向前伸，交叉在身体前面。 感受胸部肌肉的伸展。 保持拉伸 10-30 秒。 返回起始位置并重复所需的重复次数。', '["站直，双脚分开与肩同宽。", "将双臂伸直至两侧，与地面平行。", "慢慢地将双臂向前伸，交叉在身体前面。", "感受胸部肌肉的伸展。", "保持拉伸 10-30 秒。", "返回起始位置并重复所需的重复次数。"]', '/assets/media/exercises/images/1167-3uj0Ozg.jpg', '/assets/media/exercises/videos/1167-3uj0Ozg.gif', 'LICENSED', '© Gym visual — https://gymvisual.com/', NOW(), NOW()),
